import json, urllib.request
def tree(repo, path=""):
    url=f"https://huggingface.co/api/datasets/{repo}/tree/main/{path}"
    try:
        with urllib.request.urlopen(url, timeout=30) as r: return json.load(r)
    except Exception as e: return str(e)
for repo in ["SciCode1/SciCode","livecodebench/code_generation_lite"]:
    t=tree(repo)
    print("==",repo)
    if isinstance(t,list):
        for x in t: print(" ",x.get('type'),x.get('path'),x.get('size'))
        for x in t:
            if x.get('type')=='directory':
                for y in tree(repo,x['path']) if isinstance(tree(repo,x['path']),list) else []:
                    print("   ",y.get('type'),y.get('path'),y.get('size'))
    else: print(t)
EOF",
  "description": "List SciCode and LiveCodeBench dataset files on HF"
}

